async function dropProducts(ctx: any) {
  const { sdk } = ctx;
  const products = sdk.getInventory().filter((i: any) => /dagger|kiteshield|chainbody|platebody|platelegs|plateskirt|2h sword|battleaxe|longsword|scimitar|sword|axe|mace|helm|shield|warhammer/i.test(i.name));
