  for (const item of [...products]) {
    if (/bar|ore|pickaxe|hammer|coins/i.test(item.name)) continue;
    // avoid dropping pickaxe/hammer
    await sdk.sendDropItem(item.slot);
    await sdk.waitForTicks(1);
    dropped++;
  }
  if (dropped>0) console.log(`[Drop] Dropped ${dropped} products`);
}

