async function mineType(pattern, target) {
  const count = () => sdk.getInventory().filter(i=>pattern.test(i.name)).length;
  while (count() < target) {
    if (sdk.getInventory().length >= 28) { console.log('full'); break; }
    let rocks = sdk.getState().nearbyLocs.filter(l=>pattern.test(l.name)).filter(l=>l.optionsWithIndex.some(o=>/^mine$/i.test(o.text))).sort((a,b)=>a.distance-b.distance);
    if (rocks.length===0) { await sdk.waitForTicks(10); continue; }
    let rock = rocks[0];
    if (rock.distance>5) { await bot.walkTo(rock.x, rock.z, 2); await sdk.waitForTicks(2); }
    let cur = sdk.getState().nearbyLocs.find(l=>l.x===rock.x && l.z===rock.z && pattern.test(l.name));
    if (!cur) { await sdk.waitForTicks(3); continue; }
    let opt = cur.optionsWithIndex.find(o=>/^mine$/i.test(o.text));
    let before = sdk.getInventory().filter(i=>/ore/i.test(i.name)).length;
    await sdk.sendInteractLoc(cur.x, cur.z, cur.id, opt.opIndex);
    let w=0;
    while (w<20) {
      await sdk.waitForTicks(2);
      let after = sdk.getInventory().filter(i=>/ore/i.test(i.name)).length;
      if (after>before) break;
      if (sdk.getState().player.animId===-1 && w>4) break;
      w++;
    }
    await bot.dismissBlockingUI();
  }
}

